// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.localimport timber.log.Timberimport java.security.MessageDigestimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — KV Cache Manager (Strategy §4.4). * * Manages KV cache reuse for [LlamaCppProvider]. When a user asks a follow-up * question, the system prompt + conversation prefix are identical — the KV * cache from the previous inference is reused, and only the new tokens are * computed. This saves 40-60% compute on follow-up queries. * * ## How it works * * 1. Before each generation, the prompt is split into: *    - **Prefix**: system prompt + persona definition + conversation history *    - **Suffix**: the new user query * 2. The prefix is hashed (SHA-256 → Long). * 3. If the hash matches [cachedPrefixHash], the KV cache is reused — only *    the suffix tokens are computed. * 4. If the hash doesn't match, the full prompt is computed from scratch *    and the new prefix hash is cached. * * ## Context Shifting (Strategy §4.4) * * When the conversation exceeds the model's context window (e.g., 2048 tokens), * [shiftContext] removes the oldest tokens from the KV cache (keeping the * system prompt). This gives a Gemini-like "infinite context" experience * within the model's actual window size. * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§4.4 KV Cache Reuse & Context Shifting</a> */@Singletonclass KvCacheManager @Inject constructor() {    /** Hash of the prefix currently cached in the KV cache (0 = no cache). */    @Volatile    private var cachedPrefixHash: Long = 0L    /** Number of tokens currently in the KV cache. */    @Volatile    private var cachedTokenCount: Int = 0    /** Maximum tokens to keep in the KV cache before shifting. */    private val maxCachedTokens: Int = 2048    /** Number of tokens to keep when shifting (system prompt + recent context). */    private val shiftKeepTokens: Int = 256    /**     * Compute the prefix hash for a prompt.     *     * The prefix is everything before the last user query — typically:     * system prompt + persona definition + conversation history.     *     * @param fullPrompt the full prompt sent to the LLM     * @param newQueryStart the character position where the new query begins     * @return hash of the prefix, or 0 if the prefix is empty     */    fun computePrefixHash(fullPrompt: String, newQueryStart: Int): Long {        if (newQueryStart <= 0 || newQueryStart >= fullPrompt.length) return 0L        val prefix = fullPrompt.substring(0, newQueryStart)        val md = MessageDigest.getInstance("SHA-256")        val hashBytes = md.digest(prefix.toByteArray(Charsets.UTF_8))        var hash = 0L        for (i in 0 until 8) {            hash = (hash shl 8) or (hashBytes[i].toLong() and 0xFF)        }        return hash    }    /**     * Check if the KV cache can be reused for this prompt.     *     * @param prefixHash the hash of the new prompt's prefix     * @return true if the cache is valid and can be reused     */    fun canReuseCache(prefixHash: Long): Boolean {        return prefixHash != 0L && prefixHash == cachedPrefixHash    }    /**     * Update the cached prefix hash after a successful generation.     *     * @param prefixHash the hash that was used for this generation     * @param tokensGenerated number of new tokens generated     */    fun updateCache(prefixHash: Long, tokensGenerated: Int) {        cachedPrefixHash = prefixHash        cachedTokenCount += tokensGenerated        Timber.d("KV cache updated: prefixHash=%d, totalTokens=%d", prefixHash, cachedTokenCount)    }    /**     * Clear the KV cache (e.g., when switching personas or models).     */    fun clearCache() {        cachedPrefixHash = 0L        cachedTokenCount = 0        Timber.d("KV cache cleared")    }    /**     * Check if context shifting is needed.     *     * Strategy §4.4: "When the conversation exceeds the model's context window,     * llama_kv_cache_seq_rm removes the oldest tokens."     *     * @param contextLength the model's maximum context length     * @return true if shifting is needed     */    fun needsShifting(contextLength: Int): Boolean {        return cachedTokenCount >= contextLength - shiftKeepTokens    }    /**     * Get the number of tokens to keep and shift when context shifting.     *     * @return Pair(nKeep, nShift) — nKeep = tokens to preserve (system prompt),     *         nShift = tokens to remove from the middle     */    fun getShiftParams(): Pair<Int, Int> {        val nKeep = shiftKeepTokens        val nShift = (cachedTokenCount - shiftKeepTokens).coerceAtLeast(0)        return Pair(nKeep, nShift)    }    /**     * Record that context shifting was performed.     *     * @param nShift number of tokens removed     */    fun recordShift(nShift: Int) {        cachedTokenCount -= nShift        Timber.d("KV cache shifted: removed %d tokens, remaining=%d", nShift, cachedTokenCount)    }    /** Get the current cached token count (for telemetry). */    fun getCachedTokenCount(): Int = cachedTokenCount    /** Get the current cached prefix hash (for debugging). */    fun getCachedPrefixHash(): Long = cachedPrefixHash}